        <span class="sv-go"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></span>
      </a>
      <a class="sv" href="#contact" data-goto="meeting" data-svc="directory">
        <span class="sv-n">07</span>
        <span class="sv-ic"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 21h18M5 21V7l7-4 7 4v14M9 21v-6h6v6"/></svg></span>
        <h3 data-i18n="adv.s7">Company directory</h3>
        <p data-i18n="adv.s7d">Verified profiles and featured placement in the directory.</p>
        <span class="sv-go"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></span>
      </a>
      <a class="sv" href="#contact" data-goto="meeting" data-svc="market-entry">
        <span class="sv-n">08</span>
        <span class="sv-ic"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1.5"/></svg></span>
        <h3 data-i18n="adv.s8">Market entry campaigns</h3>
        <p data-i18n="adv.s8d">Positioning, content, account targeting and lead generation support for the Saudi market.</p>
        <span class="sv-go"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></span>
      </a>
    </div>

    <div class="aud-block">
      <h3 class="aud-title" data-i18n="aud.title">Who you reach</h3>
      <div class="au-grid">
        <div class="au"><span class="au-ic"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 18h20M4 18a8 8 0 0 1 16 0"/><path d="M12 6v5M9 7.5l1.2 3.5M15 7.5l-1.2 3.5"/></svg></span><p data-i18n="aud.1">Mining operators &amp; licence holders</p></div>
        <div class="au"><span class="au-ic"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg></span><p data-i18n="aud.2">International mining &amp; exploration companies</p></div>
        <div class="au"><span class="au-ic"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 21h18M4 10h16M12 3 3 8h18zM6 10v8M10 10v8M14 10v8M18 10v8"/></svg></span><p data-i18n="aud.3">Government, investors &amp; funds</p></div>
        <div class="au"><span class="au-ic"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M2 12h3M19 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1"/></svg></span><p data-i18n="aud.4">Technology, drilling &amp; equipment providers</p></div>
        <div class="au"><span class="au-ic"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m12 2 10 5-10 5L2 7z"/><path d="m2 12 10 5 10-5M2 17l10 5 10-5"/></svg></span><p data-i18n="aud.5">Geologists, engineers &amp; managers</p></div>
