    <div class="contact" id="contact">
      <div>
        <h2 class="ct-title" data-i18n="ct.title">Let’s <span>talk</span></h2>
        <p class="ct-sub" data-i18n="ct.h">Request the media kit or book a marketing meeting</p>
        <p class="ct-p" data-i18n="ct.p">Tell us about your company and goals. We’ll send the media kit or set up a meeting to plan the right mix.</p>
        <ul class="ct-list">
          <li><span><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h5"/></svg></span><b data-i18n="ct.b1">Audience, reach and channel details</b></li>
          <li><span><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M3 9h18M8 2v4M16 2v4"/></svg></span><b data-i18n="ct.b3">A marketing meeting at a time that suits you</b></li>
          <li><span><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1.5"/></svg></span><b data-i18n="ct.b2">Options built around your goal in the Saudi market</b></li>
        </ul>
      </div>
      <form class="lead" id="leadForm" novalidate>
        <input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">
        <div class="req-type" role="radiogroup" aria-label="Request type">
          <label><input type="radio" name="requestType" value="media-kit" checked><span data-i18n="cta.kit">Request the Media Kit</span></label>
          <label><input type="radio" name="requestType" value="meeting"><span data-i18n="cta.meeting">Book a Marketing Meeting</span></label>
        </div>
        <div class="fgrid">
          <div class="field"><label for="f-name" data-i18n="f.name">Name</label><input id="f-name" name="name" autocomplete="name" required></div>
          <div class="field"><label for="f-email" data-i18n="f.email">Email</label><input id="f-email" name="email" type="email" autocomplete="email" required></div>
          <div class="field"><label for="f-company" data-i18n="f.company">Company</label><input id="f-company" name="company" autocomplete="organization" required></div>
          <div class="field"><label for="f-service" data-i18n="f.service">Service of interest</label>
            <select id="f-service" name="service">
              <option value="" data-i18n="f.select">Select a service</option>
              <option value="articles" data-i18n="adv.s1">Featured articles</option>
              <option value="magazine" data-i18n="adv.s2">Magazine coverage</option>
              <option value="interviews" data-i18n="adv.s3">Interviews &amp; video</option>
              <option value="events" data-i18n="adv.s4">Event coverage</option>
              <option value="newsletter" data-i18n="adv.s5">Newsletter &amp; email</option>
              <option value="linkedin" data-i18n="adv.s6">LinkedIn &amp; social</option>
              <option value="directory" data-i18n="adv.s7">Company directory</option>
              <option value="market-entry" data-i18n="adv.s8">Market entry campaigns</option>
              <option value="unsure" data-i18n="f.unsure">Not sure yet</option>
            </select>
          </div>
          <fieldset class="field full">
            <legend data-i18n="f.goal">Your goal</legend>
            <div class="goals">
              <label><input type="checkbox" name="goals" value="market-entry"><span data-i18n="g.1">Market entry</span></label>
              <label><input type="checkbox" name="goals" value="brand-awareness"><span data-i18n="g.2">Brand awareness</span></label>
              <label><input type="checkbox" name="goals" value="decision-makers"><span data-i18n="g.3">Reach decision-makers</span></label>
              <label><input type="checkbox" name="goals" value="lead-generation"><span data-i18n="g.4">Lead generation</span></label>
              <label><input type="checkbox" name="goals" value="event-promotion"><span data-i18n="g.5">Event promotion</span></label>
              <label><input type="checkbox" name="goals" value="executive-visibility"><span data-i18n="g.6">Executive visibility</span></label>
            </div>
          </fieldset>
          <div class="field full"><label for="f-details" data-i18n="f.details">Additional details</label><textarea id="f-details" name="details"></textarea></div>
        </div>
        <button class="btn btn-gold" type="submit" data-i18n="f.submit">Send request</button>
        <div class="form-msg" id="formMsg" role="status" aria-live="polite"></div>
      </form>
    </div>
  </div>
</section>
